import Component from 'flarum/common/Component';
import { ui } from '../utils/store';
let chunk = null;
export const petChunk = () => chunk;
let loading = null;

/** The art and the card's insides: fetched once, after the page is drawn. */
export function loadPet() {
  loading ??= import(/* webpackChunkName: 'forum/pet', webpackMode: 'lazy-once' */ '../pet').then(pet => {
    chunk = pet;
    m.redraw();
  });
  return loading;
}
function whenIdle(fn) {
  if ('requestIdleCallback' in window) window.requestIdleCallback(fn, {
    timeout: 1500
  });else window.setTimeout(fn, 200);
}

/**
 * Where the pet's card goes (the sidebar, the corner's pop-up): a quiet
 * placeholder of the same size until the chunk arrives, so nothing jumps.
 */
export default class PetShell extends Component {
  oncreate(vnode) {
    super.oncreate(vnode);
    if (this.attrs.variant === 'sidebar') ui.sidebar = true;
    whenIdle(loadPet);
  }
  onremove(vnode) {
    super.onremove(vnode);
    if (this.attrs.variant === 'sidebar') ui.sidebar = false;
  }
  view() {
    if (chunk) return chunk.panel(this.attrs.variant);
    return m("div", {
      className: `PetCard PetCard--${this.attrs.variant} PetCard--loading`,
      "aria-busy": "true"
    }, m("div", {
      className: "PetCard-stage PetScene"
    }));
  }
}
flarum.reg.add('ernestdefoe-forum-pet', 'forum/components/PetShell', PetShell);