import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import LinkButton from 'flarum/common/components/LinkButton';
import { celebration, petState, t } from '../utils/store';
const KEY = 'forumPet.banner';
let gone = null;
function dismissed(key) {
  if (gone === key) return true;
  try {
    return localStorage.getItem(KEY) === key;
  } catch {
    return false;
  }
}

/** Evolution day, or a post-count milestone: a banner on the discussion list for the day. */
export default class Banner extends Component {
  view() {
    const s = petState();
    const c = celebration(s);
    if (!c || dismissed(c.key)) return null;
    return m("div", {
      className: "PetBanner",
      role: "status"
    }, m("div", {
      className: "container PetBanner-inner"
    }, m("span", {
      className: "PetBanner-icon",
      "aria-hidden": "true"
    }, m("i", {
      className: "fas fa-champagne-glasses"
    })), m("span", {
      className: "PetBanner-text"
    }, c.text), m(LinkButton, {
      className: "Button Button--primary PetBanner-go",
      href: app.route('forumPet')
    }, t('banner.visit', {
      pet: s.name
    })), m(Button, {
      className: "Button Button--icon Button--link PetBanner-close",
      icon: "fas fa-times",
      "aria-label": t('banner.dismiss'),
      onclick: () => {
        gone = c.key;
        try {
          localStorage.setItem(KEY, c.key);
        } catch {
          // Private mode: it stays for this page view.
        }
      }
    })));
  }
}
flarum.reg.add('ernestdefoe-forum-pet', 'forum/components/Banner', Banner);